// 1. 先做安全检查
if (!context.panel.data.series || context.panel.data.series.length === 0) {
  return {};
}

console.log("context.panel.data=", context.panel.data)

// 2. 获取第一个查询的结果
const series = context.panel.data.series[0];

// 3. 找到时间和数值字段
// 我们可以通过字段名来查找，这样更稳健
const timeField = series.fields.find(field => field.name === 'time');
const amountField = series.fields.find(field => field.name === 'amount');
const recordField = series.fields.find(field => field.name === 'recordCount');
const oppField = series.fields.find(field => field.name === 'oppCount');

// 4. "解包" 并转换数据
// .values 不是一个标准的 JS 数组，需要用 .toArray() 来转换
const timeData = timeField.values.toArray();
const amountData = amountField.values.toArray();
const recordData = recordField.values.toArray();
const oppData = oppField.values.toArray();



const colors = ['#5470C6', '#91CC75', '#EE6666'];

const amountLineStyle = {
  color: colors[0]
};
const recordLineStyle = {
  color: colors[1]
};
const oppLineStyle = {
  color: colors[2]
};

/**
 * Enable Data Zoom by default
 */
setTimeout(() => context.panel.chart.dispatchAction({
  type: 'takeGlobalCursor',
  key: 'dataZoomSelect',
  dataZoomSelectActive: true,
}), 500);

/**
 * Update Time Range on Zoom
 */
context.panel.chart.on('datazoom', function (params) {
  const startValue = params.batch[0]?.startValue;
  const endValue = params.batch[0]?.endValue;
  locationService.partial({ from: startValue, to: endValue });
});


const amountFormatter = function (value) {
  if ((value / (100000000)) > 1) {
    return (value / (100000000)).toFixed(2) + " 亿";
  } else if ((value / (10000000)) > 1) {
    return (value / (10000000)).toFixed(2) + " 千万"
  } else if ((value / (1000000)) > 1) {
    return (value / (1000000)).toFixed(2) + " 百万";
  } else if ((value / (100000)) > 1) {
    return (value / (100000)).toFixed(2) + " 十万";
  } else if ((value / (10000)) > 1) {
    return (value / (10000)).toFixed(2) + " 万";
  } else {
    return value + " 元";
  }
}


